const sd = $getWorkflowStaticData('global');
const report = $json;
const jobs = (((report.playback_performance || {}).jobs) || []);
const speeds = jobs.map(j => j.speed).filter(v => Number.isFinite(v));
const riskJobs = jobs.filter(j => Number.isFinite(j.speed) && j.speed < 1.0);
const warnJobs = jobs.filter(j => Number.isFinite(j.speed) && j.speed < 1.15);
const errors = jobs.filter(j => j.read_ok === false);
const fingerprint = riskJobs.map(j => `${j.path || j.log}:${j.speed}`).join('|') || 'healthy';
const now = Date.now();
const previous = sd.playback || { fingerprint: null, consecutiveRisk: 0, lastAlertAt: 0 };
const risk = riskJobs.length > 0;
const measurementFailure = errors.length > 0 || !report.playback_performance || !Array.isArray(report.playback_performance.jobs);
const measurementFingerprint = measurementFailure ? 'measurement_unavailable' : null;
const failureFingerprint = measurementFingerprint;
const consecutiveRisk = risk ? (previous.fingerprint === fingerprint ? previous.consecutiveRisk + 1 : 1) : 0;
const consecutiveFailure = measurementFailure ? (previous.failureFingerprint === failureFingerprint ? (previous.consecutiveFailure || 0) + 1 : 1) : 0;
sd.playback = { fingerprint, consecutiveRisk, lastAlertAt: previous.lastAlertAt || 0, failureFingerprint, consecutiveFailure };
const alert = risk && consecutiveRisk >= 2 && now - sd.playback.lastAlertAt > 3600000;
if (alert) sd.playback.lastAlertAt = now;
const fmt = jobs.map(j => `${(j.path || j.log).split('/').pop()}: ${j.speed == null ? 'ukjent' : j.speed.toFixed(2) + 'x'}${j.throttle_buffer_s == null ? '' : ', buffer ' + j.throttle_buffer_s + 's'}`).join('\n');
return [{ json: { notify: alert, title: risk ? 'Emby: transcode under sanntid' : 'Emby: playback normalisert', message: `Aktive jobber: ${jobs.length}.\n${fmt || 'Ingen lesbare transcodejobber.'}\nVedvarende risikoprøver: ${consecutiveRisk}.`, metrics: { jobs: jobs.length, speeds, risk_jobs: riskJobs.length, warning_jobs: warnJobs.length, errors: errors.length, consecutive_risk: consecutiveRisk, measurement_failure: measurementFailure, consecutive_failure: consecutiveFailure }, read_only: true, recovery_allowed: false } }];
